import * as THREE from '../vendor/three/three.module.js';
function part(g,name,geometry,color,pos=[0,0,0],scale=[1,1,1],extra={}){const m=new THREE.Mesh(geometry,new THREE.MeshStandardMaterial({color,roughness:.62,...extra}));m.name=name;m.position.set(...pos);m.scale.set(...scale);m.castShadow=true;m.receiveShadow=true;g.add(m);return m;}
function ball(g,name,color,pos,scale,extra){return part(g,name,new THREE.SphereGeometry(1,12,8),color,pos,scale,extra);}
function box(g,name,color,pos,scale,extra){return part(g,name,new THREE.BoxGeometry(1,1,1),color,pos,scale,extra);}
function link(g,name,a,b,r,color){const av=new THREE.Vector3(...a),bv=new THREE.Vector3(...b),d=bv.clone().sub(av);const m=part(g,name,new THREE.CylinderGeometry(r,r,d.length(),7),color);m.position.copy(av).add(bv).multiplyScalar(.5);m.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),d.normalize());return m;}
function group(parent,name,pos=[0,0,0]){const g=new THREE.Group();g.name=name;g.position.set(...pos);parent.add(g);return g;}
