  ball(root,'paint-hull',color,[0,0,0],[1.06,.88,1.75],{metalness:.25,roughness:.36});ball(root,'canopy',0x124f62,[0,.15,1.33],[.73,.6,.61],{metalness:.58,roughness:.16});part(root,'porthole-rim',new THREE.TorusGeometry(.6,.065,8,24),0xe2c57d,[0,.15,1.7]);ball(root,'canopy-glint',0x91d8d8,[-.22,.38,1.87],[.19,.08,.035]);
  for(const sign of [-1,1]){box(root,'paint-fin',color,[sign*1.12,-.12,-.5],[1.1,.12,.72]);box(root,'fin-tip',0x1f5252,[sign*1.58,-.12,-.5],[.16,.15,.75]);ball(root,'headlight',0xf9f0a7,[sign*.58,-.42,1.45],[.18,.16,.15],{emissive:0xfbefaa,emissiveIntensity:1.3});}
