  box(root,'chassis',0x304348,[0,-.16,0],[1.8,.38,2.75]);box(root,'paint-hood',color,[0,.19,1],[1.65,.48,1.2]);box(root,'paint-rear',color,[0,.15,-1],[1.65,.42,.85]);box(root,'seat',0x233235,[0,.3,-.2],[.9,.7,.7]);box(root,'seat-back',0x273b3d,[0,.65,-.55],[.95,.95,.2]);
