  for(let i=0;i<4;i++){const x=i%2?1.16:-1.16,z=i<2?1.04:-1.02,wheel=group(root,'wheel'+i,[x,-.31,z]);const tire=part(wheel,'tire',new THREE.CylinderGeometry(.61,.61,.48,14),0x203637);tire.rotation.z=Math.PI/2;const hub=part(wheel,'hub',new THREE.CylinderGeometry(.28,.28,.51,10),0xd9cd9c);hub.rotation.z=Math.PI/2;for(let j=0;j<12;j++){const a=j/12*Math.PI*2,tread=box(wheel,'tread',0x172b2b,[0,Math.cos(a)*.61,Math.sin(a)*.61],[.5,.13,.14]);tread.rotation.x=a;}link(root,'suspension',[x*.65,-.05,z],[x,-.31,z],.095,0xaba77e);}
  link(root,'bumper',[-1.1,-.2,1.74],[1.1,-.2,1.74],.12,0x254443);for(const x of [-.55,.55])ball(root,'headlight',0xffefb2,[x,.25,1.65],[.2,.17,.08],{emissive:0xffeaaa,emissiveIntensity:.7});link(root,'antenna',[.7,.5,-1.05],[.8,2,-1.2],.026,0x283f3b);box(root,'paint-flag',color,[.97,1.86,-1.2],[.4,.3,.035]);
